package com.example.starter.plan;

/**
 * 日计划状态：DRAFT 草稿 / PUBLISHED 已发布 / CANCELLED 已取消。
 */
public enum PlanStatus {
    /** 草稿：可整体替换占用，可发布。 */
    DRAFT,
    /** 已发布：时隙对外生效，不可再修改，可取消。 */
    PUBLISHED,
    /** 已取消：时隙立即释放，历史数据保留，不可再修改。 */
    CANCELLED
}

package com.example.starter.plan;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 区段占用输入：列车编号、区段 ID 与 UTC 起止时刻（左闭右开）。
 *
 * @param trainNo 列车编号
 * @param sectionId 区段 ID
 * @param startUtc 占用开始时刻（UTC，左闭）
 * @param endUtc 占用结束时刻（UTC，右开），必须晚于开始
 */
public record OccupancyInput(
        @NotBlank String trainNo,
        @NotBlank String sectionId,
        @NotNull Instant startUtc,
        @NotNull Instant endUtc) {
}

package com.example.starter.plan;

import java.time.LocalDate;
import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 创建草稿计划请求。
 *
 * @param requestKey 幂等键
 * @param scheduleKey 计划业务键，全局唯一
 * @param operatingDate 运营日期（Asia/Shanghai 日历日）
 * @param occupancies 区段占用清单，1～30 条
 */
public record CreatePlanRequest(
        @NotBlank String requestKey,
        @NotBlank String scheduleKey,
        @NotNull LocalDate operatingDate,
        @NotNull @Size(min = 1, max = 30) List<@Valid OccupancyInput> occupancies) {
}

