package com.example.starter.plan;

import java.util.List;

/**
 * 时隙冲突明细：冲突区段与发生冲突的已发布计划。
 *
 * @param sectionId 冲突区段 ID
 * @param trainNo 本计划冲突占用的列车编号
 * @param conflictingScheduleKey 与本计划冲突的已发布计划业务键；计划内列车自冲突时为 null
 */
public record ConflictDetail(String sectionId, String trainNo, String conflictingScheduleKey) {

    /**
     * 合并多条冲突明细为不可变列表。
     */
    public static List<ConflictDetail> listOf(ConflictDetail... details) {
        return List.of(details);
    }
}

package com.example.starter.plan;

import java.util.List;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带可区分的 HTTP 状态码、稳定错误码与可选冲突明细。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;
    private final transient List<ConflictDetail> conflicts;

    public ApiException(HttpStatus status, String code, String message) {
        this(status, code, message, null);
    }

    public ApiException(HttpStatus status, String code, String message, List<ConflictDetail> conflicts) {
        super(message);
        this.status = status;
        this.code = code;
        this.conflicts = conflicts;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    public List<ConflictDetail> conflicts() {
        return conflicts;
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, "VALIDATION_ERROR", message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    public static ApiException slotConflict(String message, List<ConflictDetail> conflicts) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT", message, conflicts);
    }
}

package com.example.starter.plan;

import java.util.List;

/**
 * 统一错误响应体。
 *
 * @param code 稳定错误码，用于区分 400/404/409/422 的具体原因
 * @param message 人类可读的错误描述
 * @param conflicts 时隙冲突明细，仅 422 时非空
 */
public record ErrorResponse(String code, String message, List<ConflictDetail> conflicts) {
}

